#### Phase 3: Continuous Verification (Weeks 9-12)

**Real-Time Risk Scoring:**

```csharp
// ASP.NET Core: Middleware for continuous authorization
public class ZeroTrustMiddleware
{
    public async Task InvokeAsync(HttpContext context)
    {
        // 1. Extract user identity from JWT
        var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;

        // 2. Calculate real-time risk score
        var riskScore = await _riskEngine.CalculateRiskScore(new RiskContext
        {
            UserId = userId,
            SourceIP = context.Connection.RemoteIpAddress,
            DeviceId = context.Request.Headers["X-Device-Id"],
            LastAuthTime = GetLastAuthTime(context),
            RequestedResource = context.Request.Path,
            Time = DateTime.UtcNow
        });

        // 3. Re-authenticate if risk threshold exceeded
        if (riskScore > _options.RiskThreshold)
        {
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "reauthentication_required",
                message = "Risk level elevated, please re-authenticate",
                risk_score = riskScore
            });
            return;
        }

        // 4. Query OPA for policy decision
        var allowed = await _opaClient.Evaluate("api/authz/allow", new
        {
            user = userId,
            action = context.Request.Method,
            resource = context.Request.Path,
            risk_score = riskScore,
            device_compliant = context.Request.Headers["X-Device-Compliant"] == "true"
        });

        if (!allowed)
        {
            context.Response.StatusCode = 403;
            await context.Response.WriteAsJsonAsync(new { error = "policy_denied" });
            return;
        }

        await _next(context);
    }
}
```

